using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;
using Parcs.Agent.Runtime;

public class R { public int k { get; set; } public double value { get; set; } }

public class Sub : IAgentComputation
{
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct)
    {
        int k = int.Parse(input.WorkerInput.Trim());
        double a = 8.0 * k / 32.0, b = 8.0 * (k + 1) / 32.0;
        int n = 10000;
        double h = (b - a) / n;
        Func<double, double> f = x => Math.Exp(-x / 4.0) * Math.Cos(x + 0.5 * Math.Sin(2 * x));
        double s = f(a) + f(b);
        for (int i = 1; i < n; i++)
        {
            double x = a + i * h;
            s += (i % 2 == 1 ? 4.0 : 2.0) * f(x);
        }
        s *= h / 3.0;
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new R { k = k, value = s })));
    }
}

public class Reduce : IAgentComputation
{
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct)
    {
        double total = 0;
        int count = 0;
        for (int j = 0; j < 32; j++)
        {
            var o = input.GetPreviousOutputs(j);
            if (o == null || o.Count == 0 || o[0] == null) continue;
            var r = JsonSerializer.Deserialize<R>(o[0]);
            total += r.value;
            count++;
        }
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new { parts = count, integral = total })));
    }
}

